        return S.status_label(status)
    except Exception:
        return status or "—"

def _razobrat(znachenie):
    znachenie = (znachenie or "").strip()
    if not znachenie:
        return None
    for obr in ("%Y-%m-%d", "%d.%m.%Y", "%Y-%m-%dT%H:%M:%S"):
        try:
            return time.mktime(time.strptime(znachenie[:19], obr))
        except Exception:
            continue
    return None

def _krasivo(znachenie):
    metka = _razobrat(znachenie)
    if metka is None:
        return (znachenie or "").strip()
    t = time.localtime(metka)
    return "%d %s %d" % (t.tm_mday, MESYACY[t.tm_mon - 1], t.tm_year)

def _v_iso(text):
    t = (text or "").strip().replace("/", ".").replace(" ", "")
    for obr in ("%d.%m.%Y", "%d.%m.%y", "%Y-%m-%d"):
        try:
            razobrano = time.strptime(t, obr)
            if razobrano.tm_year < 2000 or razobrano.tm_year > 2100:
                return ""
            return time.strftime("%Y-%m-%d", razobrano)
        except Exception:
            continue
    return ""

def _dney_do(card):
    """Дни до выдачи: ручная дата важнее, иначе отправление + 75."""
    ruchnaya = _razobrat(card.get("eta_manual"))
    otpravka = _razobrat(card.get("sea_date_out"))
    if ruchnaya is not None:
        cel = ruchnaya
    elif otpravka is not None:
        cel = otpravka + DNEY_PUTI * 86400
    else:
        return None, None
    seychas = time.strftime("%Y-%m-%d", time.localtime(time.time() + 7 * 3600))
    try:
        a = time.mktime(time.strptime(seychas, "%Y-%m-%d"))
        b = time.mktime(time.strptime(time.strftime("%Y-%m-%d",
                                                    time.localtime(cel)),
                                      "%Y-%m-%d"))
        dney = max(int(round((b - a) / 86400.0)), 0)
    except Exception:
        dney = 0
    return dney, cel

