    context.user_data["cont_wait"] = {"card_id": cid, "field": pole}

def _svezhiy_sborshchik():
    """Пересборка из бота обязана брать свежий stranica.py, а не копию
    из памяти процесса — иначе старый код затирает новые страницы."""
    try:
        import cars_ui
    except Exception as e:
        log.warning("konteyner: cars_ui не импортирован: %s", e)
        return
    imya = "_peresobrat_stranicy"
    ishodnaya = getattr(cars_ui, imya, None)
    if ishodnaya is None or getattr(ishodnaya, "_v172", False):
        return

    def obertka(*a, **k):
        try:
            import stranica
            importlib.reload(stranica)
        except Exception as e:
            log.warning("konteyner: stranica не перезагружена: %s", e)
        return ishodnaya(*a, **k)

    obertka._v172 = True
    setattr(cars_ui, imya, obertka)
    log.info("konteyner: пересборка из бота переведена на свежий stranica.py")

def _v173_chitat():
    try:
        with open(V173_PAMYAT, "r", encoding="utf-8") as f:
            d = _j173.loads(f.read() or "{}")
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}

def _v173_pisat(d):
    try:
        vremenno = V173_PAMYAT + ".tmp"
        with open(vremenno, "w", encoding="utf-8") as f:
            f.write(_j173.dumps(d, ensure_ascii=False))
        _o173.replace(vremenno, V173_PAMYAT)
        return True
    except Exception as e:
        log.warning("konteyner: срок не записан: %s", e)
        return False

def _v173_zafiksirovat(nomer_mashiny, kto="бот"):
    """Пишет дату выезда ОДИН раз. Возвращает (дата, впервые_ли)."""
    if not nomer_mashiny:
        return "", False
    pamyat = _v173_chitat()
    zapis = pamyat.get(nomer_mashiny) or {}
    bylo = (zapis.get("vyehal") or "").strip()
    if bylo:
        return bylo, False
    segodnya = _v173_segodnya()
    pamyat[nomer_mashiny] = {"vyehal": segodnya, "postavil": kto,
                             "kogda": time.strftime("%Y-%m-%d %H:%M:%S")}
    _v173_pisat(pamyat)
    return segodnya, True
